package com.bank.ledger;

import java.util.Arrays;
import java.util.logging.Logger;

public class CorruptPairDemo {
    private static final Logger log = Logger.getLogger(CorruptPairDemo.class.getName());

    public static void main(String[] args) {
        int[] ledger = {3, 1, 2, 5, 2};   // n=5, 2 duplicated, 4 missing
        log.info("Ledger page numbers: " + Arrays.toString(ledger));

        LedgerIntegrityChecker checker = new LedgerIntegrityChecker();
        int[] pair = checker.findCorruptPair(ledger);

        log.info("Corrupt pair [duplicate, missing]: " + Arrays.toString(pair));
    }
}
