package com.bank.ledger;

public class LedgerIntegrityChecker {

    public int[] findCorruptPair(int[] pages) {
        int i = 0, n = pages.length;
        while (i < n) {
            int target = pages[i] - 1;
            if (pages[i] != pages[target]) {
                int tmp = pages[i]; pages[i] = pages[target]; pages[target] = tmp;
            } else {
                i++;
            }
        }
        // Exactly one slot is wrong: value = duplicate, index+1 = missing.
        for (int idx = 0; idx < n; idx++) {
            if (pages[idx] != idx + 1) {
                return new int[]{pages[idx], idx + 1};
            }
        }
        return new int[]{-1, -1};   // no corruption
    }
}
